      "statement": "vmax0p9_idx = fclks->num_levels - 1;",
      "reason": "When num_levels is 0, the unsigned subtraction wraps around to UINT_MAX."
    },
    {
      "statement": "(fclks->data[vmid0p72_idx].clocks_in_khz / 1000.0)",
      "reason": "Uses the wrapped index to read far outside fclks->data (out-of-bounds read)."
    },
    {
      "statement": "(fclks->data[vnom0p8_idx].clocks_in_khz / 1000.0)",
      "reason": "Uses the wrapped index to read far outside fclks->data (out-of-bounds read)."
    },
    {
      "statement": "(fclks->data[vmax0p9_idx].clocks_in_khz / 1000.0)",
      "reason": "Uses the wrapped index to read far outside fclks->data (out-of-bounds read)."
    }
